node -e "
const fs = require('fs');
const { execSync } = require('child_process');

try {
  // Only deploy if running in workspace
  const apkPath = 'd:\\\\NishaanTech\\\\state-quest-adventure\\\\android\\\\app\\\\build\\\\outputs\\\\apk\\\\debug\\\\app-debug.apk';

  if (fs.existsSync(apkPath)) {
    console.log('[PostBuild] Starting Android gradle build...');
    execSync('d:\\\\NishaanTech\\\\state-quest-adventure\\\\android\\\\gradlew.bat clean assembleDebug', {
      cwd: 'd:\\\\NishaanTech\\\\state-quest-adventure\\\\android',
      stdio: 'inherit'
    });

    console.log('[PostBuild] APK built, installing on device...');
    execSync('adb install -r \"' + apkPath + '\"', { stdio: 'inherit' });
    console.log('[PostBuild] ✅ APK installed on device');

    console.log('[PostBuild] Launching app...');
    execSync('adb shell am start -n com.nishaantech.exploreindia/.MainActivity', { stdio: 'inherit' });
    console.log('[PostBuild] ✅ App launched');
  }
} catch (error) {
  // Non-fatal - build succeeded but deployment failed
  console.warn('[PostBuild] Deploy skipped - device may be offline');
}
"
